INSERT INTO price_sale (name, slug, owner_type, seller_profile_id, sale_type, discount_type, discount_value,
                        max_discount_per_unit, scope_type, scope_ids, conditions, min_unit_price,
                        per_listing_quota, per_buyer_limit, budget_cap, subsidy_reserved, budget_exhausted_at,
                        banner_image_url, featured_on_home, home_sort, starts_at, ends_at,
                        paused_at, paused_by, pause_reason, created_by, created_at, updated_at)
SELECT v.name, v.slug, v.owner_type,
       CASE WHEN v.shop IS NOT NULL THEN pg_temp.spid(v.shop) END,
       v.sale_type, v.discount_type, v.discount_value, v.max_per_unit, v.scope_type,
       CASE v.scope_type
            WHEN 'GAME' THEN ARRAY[(SELECT g.id FROM game g WHERE g.code = v.scope_code)]::bigint[]
            WHEN 'CARD_SET' THEN ARRAY[(SELECT s.id FROM card_set s WHERE s.code = v.scope_code)]::bigint[]
            ELSE '{}'::bigint[] END,
       '{}', NULL, NULL, NULL, v.budget, 0, NULL, NULL, v.home_sort IS NOT NULL, v.home_sort,
       pg_temp.ago(v.start_days), pg_temp.ago(v.end_days), NULL, NULL, NULL,
       pg_temp.uid(coalesce(v.shop, 'admin')), pg_temp.ago(greatest(v.start_days, 0) + 1), pg_temp.ago(greatest(v.start_days, 0) + 1)
  FROM (VALUES
        ('Phantasmal Flames Launch', 'phantasmal-flames-launch', 'PLATFORM', NULL::text, 'CATEGORY_SALE', 'PERCENT', 12::numeric,
         800::numeric, 'CARD_SET', 'PFL', 60000::numeric, 5::int, 4::numeric, -9::numeric),
        ('Chainsaw Man Week', 'chainsaw-man-week', 'PLATFORM', NULL, 'CATEGORY_SALE', 'PERCENT', 10,
         500, 'CARD_SET', 'UE22BT', 30000, 6, 2, -5),
        ('Straw Hat ลดทั้งร้าน 7%', 'strawhat-7', 'SELLER', 'strawhat_market', 'SHOP_SALE', 'PERCENT', 7,
         NULL, 'SHOP', NULL, NULL, NULL, 3, -4),
        ('Eevee House ลดทั้งร้าน 5%', 'eevee-house-5', 'SELLER', 'eevee_house', 'SHOP_SALE', 'PERCENT', 5,
         NULL, 'SHOP', NULL, NULL, NULL, 6, -8),
        ('Mana Forge Commander Night', 'mana-forge-commander-night', 'SELLER', 'mana_forge', 'SHOP_SALE', 'PERCENT', 10,
